import * as React from "react"

import { cn } from "@/lib/utils"

type GridProps = React.ComponentProps<"div"> & {
  /** rules: faint hairlines, as the posters lay a construction grid under the words. dots: a fine point at each crossing, as a drafting sheet is dotted. */
  variant?: "rules" | "dots"
  /** The side of one square: a number of pixels or any CSS length. The content stands one cell in, on a line. */
  cell?: number | string
}

// ponytail: a fixed run of labels, clipped by the box; past column 48 or row Z the lines go on unlabelled.
const COLUMNS = Array.from({ length: 48 }, (_, i) => String(i + 1).padStart(2, "0"))
const CORNERS = ["start-top", "end-top", "start-foot", "end-foot"]
const ROWS = Array.from({ length: 26 }, (_, i) => String.fromCharCode(65 + i))

/**
 * A quiet structure behind a section: a faint square grid, a registration cross at each corner, and the columns
 * numbered along the top and the rows lettered down the start edge, like a drafting sheet. It never moves.
 */
function Grid({ variant = "rules", cell, className, style, children, ...props }: GridProps) {
  const size = typeof cell === "number" ? `${cell}px` : cell
  return (
    <div
      data-slot="grid"
      data-variant={variant}
      className={cn("db-grid", className)}
      style={size ? ({ "--db-grid-cell": size, ...style } as React.CSSProperties) : style}
      {...props}
    >
      {CORNERS.map((c) => <span key={c} className="db-grid-cross" data-corner={c} aria-hidden="true" />)}
      <span className="db-grid-ticks" data-axis="columns" aria-hidden="true">
        {COLUMNS.map((n) => <span key={n}>{n}</span>)}
      </span>
      <span className="db-grid-ticks" data-axis="rows" aria-hidden="true">
        {ROWS.map((n) => <span key={n}>{n}</span>)}
      </span>
      {children}
    </div>
  )
}

export { Grid, type GridProps }

@layer components {
  /* ── db-grid ── a quiet structure behind a section, drawn once and never moved: a faint square grid, as "the silence that
     heals" and "Less is more." lay theirs under the words, or a fine point at each crossing, as Paul Rand's sheet is
     dotted. A registration cross stands on each corner, and the first row and column are the sheet's border: the columns
     numbered along the top, the rows lettered down the start edge, each label hugging the corner where its line begins.
     The content stands one cell in, on a line. */
  .db-grid {
    --cell: var(--db-grid-cell, var(--db-space-7));
    --line: var(--db-rule);
    --cross: calc(var(--db-space-3) + var(--db-hairline));
    position: relative; isolation: isolate; padding: var(--cell); min-width: 0;
    background-image: linear-gradient(to right, var(--line) var(--db-hairline), transparent var(--db-hairline)), linear-gradient(to bottom, var(--line) var(--db-hairline), transparent var(--db-hairline));
    background-size: var(--cell) var(--cell);
    background-position: left top;
  }
  .db-grid:is([dir="rtl"], [dir="rtl"] *) {
    background-image: linear-gradient(to left, var(--line) var(--db-hairline), transparent var(--db-hairline)), linear-gradient(to bottom, var(--line) var(--db-hairline), transparent var(--db-hairline));
    background-position: right top;
  }
  /* dots: one fine point on each crossing, the rules left out. */
  .db-grid[data-variant="dots"] {
    --line: var(--db-rule-strong);
    background-image: radial-gradient(circle, var(--line) 0 var(--db-hairline), transparent calc(var(--db-hairline) + 0.5px));
    background-position: calc(var(--cell) / -2) calc(var(--cell) / -2);
  }
  .db-grid[data-variant="dots"]:is([dir="rtl"], [dir="rtl"] *) { background-position: right calc(var(--cell) / -2) top calc(var(--cell) / -2); }

  /* The crosses: two hairlines centred on each corner of the sheet. */
  .db-grid-cross {
    position: absolute; z-index: -1; width: var(--cross); height: var(--cross); pointer-events: none;
    background: linear-gradient(var(--db-pencil), var(--db-pencil)) center / 100% var(--db-hairline) no-repeat, linear-gradient(var(--db-pencil), var(--db-pencil)) center / var(--db-hairline) 100% no-repeat;
  }
  .db-grid-cross[data-corner^="start"] { inset-inline-start: calc(var(--cross) / -2); }
  .db-grid-cross[data-corner^="end"] { inset-inline-end: calc(var(--cross) / -2); }
  .db-grid-cross[data-corner$="top"] { top: calc(var(--cross) / -2); }
  .db-grid-cross[data-corner$="foot"] { bottom: calc(var(--cross) / -2); }

  /* The border's labels: ours, so upright, small and in the pencil, in tabular figures. Only whole cells are labelled: a
     label with no room wraps onto the next line, which the strip clips away. */
  .db-grid-ticks {
    position: absolute; z-index: -1; display: flex; flex-wrap: wrap; overflow: hidden; pointer-events: none;
    font-size: var(--db-pp); line-height: 1; letter-spacing: var(--db-pp-tr); font-variant-numeric: tabular-nums lining-nums; color: var(--db-pencil);
  }
  .db-grid-ticks > span { flex: none; display: flex; box-sizing: border-box; width: var(--cell); height: var(--cell); padding: var(--db-space-1) var(--db-space-2); }
  .db-grid-ticks[data-axis="columns"] { top: 0; inset-inline: var(--cell) 0; height: var(--cell); }
  .db-grid-ticks[data-axis="columns"] > span { align-items: flex-end; }
  .db-grid-ticks[data-axis="rows"] { flex-direction: column; top: var(--cell); bottom: 0; inset-inline-start: 0; width: var(--cell); }
  .db-grid-ticks[data-axis="rows"] > span { justify-content: flex-end; }
}
